import"./style-C37hbiWi.js";const i=document.getElementById("rescan-btn"),n=document.getElementById("rescan-status"),u=document.getElementById("models-list"),m=document.getElementById("logo-input"),l=document.getElementById("logo-save-btn"),d=document.getElementById("logo-remove-btn"),o=document.getElementById("logo-status"),r=document.getElementById("logo-preview");async function f(){try{const t=await(await fetch("/models.json")).json(),s=Array.isArray(t)?t:[],c=s.map(a=>typeof a=="object"&&a.id?a.id:a);u.innerHTML=`
      <h3>Current models (${s.length})</h3>
      <ul>
        ${c.map(a=>`<li>${a}</li>`).join("")}
      </ul>
    `}catch{u.innerHTML='<p class="rescan-status error">Failed to load model list</p>'}}i.addEventListener("click",async()=>{i.disabled=!0,n.textContent="Scanning...",n.className="rescan-status";try{const e=await fetch("/api/rescan-models",{method:"POST"}),t=await e.text();if(!t)throw new Error("Empty response. Rescan API may not be available (dev server only).");let s;try{s=JSON.parse(t)}catch{throw new Error(`Invalid response: ${t.slice(0,100)}`)}if(!e.ok)throw new Error(s.error||"Rescan failed");n.textContent=`Found ${s.models.length} model(s): ${s.models.join(", ")||"none"}`,n.className="rescan-status success",f()}catch(e){n.textContent=e.message||'Rescan failed. In production, run "npm run generate-models" to update the list.',n.className="rescan-status error"}finally{i.disabled=!1}});m.addEventListener("change",e=>{const t=e.target.files[0];if(t){l.disabled=!1;const s=new FileReader;s.onload=()=>{r.innerHTML=`<img src="${s.result}" alt="Logo preview" class="logo-preview-img" />`},s.readAsDataURL(t)}else l.disabled=!0,r.innerHTML=""});l.addEventListener("click",async()=>{const e=m.files[0];if(!e)return;l.disabled=!0,o.textContent="Saving...",o.className="rescan-status";const t=new FileReader;t.onload=async()=>{try{const s=await fetch("/api/save-logo",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({logo:t.result})}),c=await s.text(),a=c?JSON.parse(c):{};if(!s.ok)throw new Error(a.error||"Save failed");o.textContent="Logo saved. Refresh the viewer to see it.",o.className="rescan-status success",g()}catch(s){o.textContent=s.message||"Failed to save logo.",o.className="rescan-status error"}finally{l.disabled=!1}},t.readAsDataURL(e)});d.addEventListener("click",async()=>{d.disabled=!0,o.textContent="Removing...",o.className="rescan-status";try{const e=await fetch("/api/remove-logo",{method:"POST"}),t=await e.text(),s=t?JSON.parse(t):{};if(!e.ok)throw new Error(s.error||"Remove failed");o.textContent="Logo removed.",o.className="rescan-status success",m.value="",r.innerHTML="",g()}catch(e){o.textContent=e.message||"Failed to remove logo.",o.className="rescan-status error"}finally{d.disabled=!1}});async function g(){try{const e=await fetch("/logo.json");if(e.ok){const{path:t}=await e.json();r.innerHTML=`<img src="${t}?t=${Date.now()}" alt="Current logo" class="logo-preview-img" />`}else r.innerHTML='<p class="logo-none">No logo set</p>'}catch{r.innerHTML='<p class="logo-none">No logo set</p>'}}f();g();
